head.script:
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue + "\n");
};



// 두 Body Column 에 동일한 editFormat 마스크 '####/##/##' (입력 길이 8자리) 를 설정한다.
scwin.onpageload = function () {
    target1.setColumnEditFormat(0, '####/##/##');
    target1.setColumnEditFormat(1, '####/##/##');
};



// 편집 입력창(공용 에디터 input) 을 찾는다.
scwin.getEditor = function (strColID) {
    return document.querySelector("input[id^='G_'][id*='" + strColID + "']");
};

// 셀 편집 -> 포커스아웃 시점의 native maxlength attribute / 편집값 / 표시값을 한 줄로 출력한다.
scwin.target1_onafteredit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    let editor = scwin.getEditor(colID);
    let maxAttr = (editor === null) ? '(편집 입력창 없음)'
                : (editor.getAttribute('maxlength') === null) ? '(설정 안 됨)' : editor.getAttribute('maxlength');
    let editVal = (editor === null) ? value : editor.value;
    let td = document.querySelector("td[id*='target1_cell_" + row + "_" + col + "']");

    scwin.setReturnValue("[" + colID + "] native maxlength attribute : " + maxAttr
        + " / 편집값 : " + editVal
        + " / 표시값 : " + (td === null ? '' : td.textContent.trim()));
};
